statement:
Decide whether the strings `s` and `t` are exactly one edit apart. One edit is one of these operations applied to `s`:

- insert a single character at any position;
- delete a single character;
- replace a single character with a different character.

Return `true` if a single such edit turns `s` into `t`, and `false` otherwise. Identical strings need zero edits, so they give `false`.

validator:
function validate([s, t]) {
  if (s.length > 10000 || t.length > 10000) return 'Each string has at most 10^4 characters.';
  if (!/^[a-zA-Z0-9]*$/.test(s) || !/^[a-zA-Z0-9]*$/.test(t)) return 'Use only letters and digits.';
  return null;
}

reference:
function isOneEditDistance(s, t) {
  if (Math.abs(s.length - t.length) > 1) {
    return false;
  }
  let i = 0;
  let j = 0;
  let edits = 0;
  while (i < s.length && j < t.length) {
    if (s[i] === t[j]) {
      i++;
      j++;
    } else {
      edits++;
      if (edits > 1) {
        return false;
      }
      if (s.length > t.length) {
        i++;
      } else if (s.length < t.length) {
        j++;
      } else {
        i++;
        j++;
      }
    }
  }
  edits += (s.length - i) + (t.length - j);
  return edits === 1;
}

brute:
function isOneEditDistance(s, t) {
  // Same length: exactly one differing position. Lengths one apart: deleting some character
  // of the longer string must give the shorter one.
  if (s.length === t.length) {
    let differences = 0;
    for (let k = 0; k < s.length; k++) if (s[k] !== t[k]) differences++;
    return differences === 1;
  }
  const shorter = s.length < t.length ? s : t;
  const longer = s.length < t.length ? t : s;
  if (longer.length - shorter.length !== 1) return false;
  for (let k = 0; k < longer.length; k++) {
    if (longer.slice(0, k) + longer.slice(k + 1) === shorter) return true;
  }
  return false;
}

generator:
function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const full = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const alphabet = size === 'large' ? full : rand() < 0.7 ? 'ab' : 'aB1';
  const randomString = length => Array.from({ length }, () => alphabet[pick(alphabet.length)]).join('');
  const edit = text => {
    const kind = pick(3);
    if (kind === 0 || text.length === 0) {
      const at = pick(text.length + 1);
      return text.slice(0, at) + alphabet[pick(alphabet.length)] + text.slice(at);
    }
    const at = pick(text.length);
    if (kind === 1) return text.slice(0, at) + text.slice(at + 1);
    const others = alphabet.split('').filter(c => c !== text[at]);
    return text.slice(0, at) + others[pick(others.length)] + text.slice(at + 1);
  };
  const s = randomString(size === 'large' ? 9000 + pick(990) : pick(7));
  const mode = pick(5);
  let t = s;
  if (mode === 1 || mode === 2) t = edit(s);
  if (mode === 3) t = edit(edit(s));
  if (mode === 4) t = randomString(size === 'large' ? 9000 + pick(990) : pick(7));
  return rand() < 0.5 ? [s, t] : [t, s];
}
